def email_host(value):
    if not isinstance(value, str):
        raise ValueError("email address must be a string")
    address = value.strip()
    if address.count("@") != 1:
        raise ValueError("email address must contain exactly one @")
    local, domain = address.split("@")
    if not local or not domain:
        raise ValueError("email address must have nonempty local and domain parts")
    if any(ch.isspace() for ch in address):
        raise ValueError("email address must not contain whitespace")
    return domain.casefold()

