import pytest
from signalbox.parse_flags import parse_flags

def test_case_1():
    assert parse_flags(" A=x ; b= ; a=Y ") == {"a": "Y", "b": ""}

def test_case_2():
    assert parse_flags("; ;") == {}

arguments.content:
def parse_flags(text):
    if not isinstance(text, str):
        raise ValueError("parse_flags expects a string")

    result = {}
    for segment in text.split(";"):
        if segment.strip() == "":
            continue
        if "=" not in segment:
            raise ValueError("flag segment missing '='")
        key, value = segment.split("=", 1)
        key = key.strip()
        if key == "":
            raise ValueError("flag segment missing key")
