import pytest
from signalbox.peak_sample import peak_sample

def test_case_1():
    assert peak_sample([2, 9, -1, 3], 2) == 0

def test_case_2():
    assert peak_sample([], 1) is None

arguments.content:
def peak_sample(samples, width):
    """Return the earliest start index of the width-sized window with the greatest sum.

    Returns None when width exceeds the number of samples. Raises ValueError for
    an invalid width or any sample that is not a plain int (bool included).
    """
    if type(width) is not int or width <= 0:
        raise ValueError("width must be a positive plain integer")

    for sample in samples:
        if type(sample) is not int:
            raise ValueError("samples must be plain integers")

    n = len(samples)
    if width > n:
        return None

    window_sum = sum(samples[:width])
    best_sum = window_sum
    best_start = 0

    for start in range(1, n - width + 1):
        window_sum += samples[start + width - 1] - samples[start - 1]
        if window_sum > best_sum:
            best_sum = window_sum
            best_start = start

    return best_start

