def _is_plain_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def allocate_quota(weights, total):
    if not _is_plain_int(total) or total < 0:
        raise ValueError("total must be a nonnegative plain integer")
    if not isinstance(weights, (list, tuple)) or len(weights) == 0:
        raise ValueError("weights must be a nonempty list of positive plain integers")
    for weight in weights:
        if not _is_plain_int(weight) or weight <= 0:
            raise ValueError("weights must be positive plain integers")

    denominator = sum(weights)
    allocations = []
    remainders = []
    for index, weight in enumerate(weights):
        numerator = total * weight
        allocations.append(numerator // denominator)
        remainders.append((numerator % denominator, index))

    remaining = total - sum(allocations)
    remainders.sort(key=lambda item: (-item[0], item[1]))
    for _, index in remainders[:remaining]:
        allocations[index] += 1

    return allocations

