def audit_gaps(events):
    """Return inclusive missing sequence ranges per stream.

    ``events`` is an iterable of ``(stream, sequence)`` pairs. Streams must be
    nonempty strings and sequences positive plain ints (bool is rejected).
    Duplicates are ignored; streams without gaps are omitted.
    """
    observed = {}
    for event in events:
        try:
            stream, sequence = event
        except (TypeError, ValueError):
            raise ValueError("each event must be a (stream, sequence) pair")
        if not isinstance(stream, str) or not stream:
            raise ValueError("stream must be a nonempty string")
        if isinstance(sequence, bool) or not isinstance(sequence, int):
            raise ValueError("sequence must be a positive plain int")
        if sequence <= 0:
            raise ValueError("sequence must be a positive plain int")
        observed.setdefault(stream, set()).add(sequence)

    gaps = {}
    for stream, sequences in observed.items():
        ordered = sorted(sequences)
        stream_gaps = []
        for previous, current in zip(ordered, ordered[1:]):
            if current - previous > 1:
                stream_gaps.append((previous + 1, current - 1))
        if stream_gaps:
            gaps[stream] = stream_gaps
    return gaps

